const adcs_vec3_t *req = mp_input.request_a_m2;
const adcs_vec3_t *fld = mp_input.field_body_t;
adcs_vec3_t zero = {0.0, 0.0, 0.0};
double reqv[3], capv[3];
int axis;
int quiet = 1;

/* 1. 校验 */
{
    int cfg_ok;
    double bnorm, rnorm;
    cfg_ok = (mp_config.max_dipole_a_m2 > 0.0) &&
             (mp_config.stop_fraction > 0.0) &&
             (mp_config.stop_fraction < mp_config.start_fraction) &&
             (mp_config.start_fraction <= 1.0) &&
             (mp_config.pulse_cycles >= 1U) && (mp_config.pulse_cycles <= 100U) &&
             (mp_config.cooldown_cycles >= 1U) && (mp_config.cooldown_cycles <= 100U) &&
             (mp_config.reversal_blank_cycles >= 1U) && (mp_config.reversal_blank_cycles <= 100U) &&
             (mp_config.max_thermal_cycles >= 1U) && (mp_config.max_thermal_cycles <= 100U) &&
             (mp_config.recovery_cycles >= 1U) && (mp_config.recovery_cycles <= 100U);

    if ((!cfg_ok) || (req == NULL) || (fld == NULL) ||
        (!adcs_is_finite_vec3(req)) || (!adcs_is_finite_vec3(fld)) ||
        ((mp_input.enable != 0) && (mp_input.enable != 1))) {
        mp_state.mode = MP_FAULT;
        mp_state.elapsed = 0U;
        mp_state.thermal_cycles = 0U;
        mp_state.recovery_count = 0U;
        mp_state.captured_a_m2 = zero;
        mp_state.last_capture_a_m2 = zero;
        mp_output.mode = mp_state.mode;
        mp_output.elapsed = 0U;
        mp_output.thermal_cycles = 0U;
        mp_output.recovery_count = 0U;
        mp_output.realized_a_m2 = zero;
        mp_output.torque_nm = zero;
        return;
    }
    bnorm = adcs_vec3_norm(fld);
    rnorm = adcs_vec3_norm(req);
    if ((bnorm < ADCS_EPS_NORM) || (rnorm < ADCS_EPS_NORM)) {
        mp_state.mode = MP_FAULT;
        mp_state.elapsed = 0U;
        mp_state.thermal_cycles = 0U;
        mp_state.recovery_count = 0U;
        mp_state.captured_a_m2 = zero;
        mp_state.last_capture_a_m2 = zero;
        mp_output.mode = mp_state.mode;
        mp_output.elapsed = 0U;
        mp_output.thermal_cycles = 0U;
        mp_output.recovery_count = 0U;
        mp_output.realized_a_m2 = zero;
        mp_output.torque_nm = zero;
        return;
    }
}

/* 2. Disable */
if (mp_input.enable == 0) {
    mp_state.mode = MP_IDLE;
    mp_state.elapsed = 0U;
    mp_state.thermal_cycles = 0U;
    mp_state.recovery_count = 0U;
    mp_state.captured_a_m2 = zero;
    mp_state.last_capture_a_m2 = zero;
    mp_output.mode = MP_IDLE;
    mp_output.elapsed = 0U;
    mp_output.thermal_cycles = 0U;
    mp_output.recovery_count = 0U;
    mp_output.realized_a_m2 = zero;
    mp_output.torque_nm = zero;
    return;
}

/* 3. FAULT 持续 */
if (mp_state.mode == MP_FAULT) {
    mp_output.mode = MP_FAULT;
    mp_output.elapsed = 0U;
    mp_output.thermal_cycles = 0U;
    mp_output.recovery_count = 0U;
    mp_output.realized_a_m2 = zero;
    mp_output.torque_nm = zero;
    return;
}

reqv[0] = req->x;
reqv[1] = req->y;
reqv[2] = req->z;

{
    double stop_thr_q = mp_config.stop_fraction * mp_config.max_dipole_a_m2;
    if ((fabs(reqv[0]) >= stop_thr_q) ||
        (fabs(reqv[1]) >= stop_thr_q) ||
        (fabs(reqv[2]) >= stop_thr_q))
        quiet = 0;
}

if (mp_state.mode == MP_IDLE) {
    double start_thr = mp_config.start_fraction * mp_config.max_dipole_a_m2;
    double stop_thr = mp_config.stop_fraction * mp_config.max_dipole_a_m2;
    double lastv[3];
    int capture_nonzero = 0;
    int oppose = 0;

    lastv[0] = mp_state.last_capture_a_m2.x;
    lastv[1] = mp_state.last_capture_a_m2.y;
    lastv[2] = mp_state.last_capture_a_m2.z;

    for (axis = 0; axis < 3; axis++) {
        double r = reqv[axis];
        double ar = fabs(r);
        double sign_r = (r >= 0.0) ? 1.0 : -1.0;
        int last_has = (lastv[axis] != 0.0);
        int matching = last_has && ((lastv[axis] > 0.0) == (r > 0.0));
        if (ar >= start_thr) {
            capv[axis] = sign_r * mp_config.max_dipole_a_m2;
        } else if (matching && (ar >= stop_thr)) {
            capv[axis] = sign_r * mp_config.max_dipole_a_m2;
        } else {
            capv[axis] = 0.0;
        }
    }

    if ((capv[0] != 0.0) || (capv[1] != 0.0) || (capv[2] != 0.0))
        capture_nonzero = 1;

    if (capture_nonzero &&
        ((lastv[0] != 0.0) || (lastv[1] != 0.0) || (lastv[2] != 0.0))) {
        double dot = capv[0] * lastv[0] + capv[1] * lastv[1] + capv[2] * lastv[2];
        if (dot < 0.0)
            oppose = 1;
    }

    if (!capture_nonzero) {
        mp_state.captured_a_m2 = zero;
        mp_state.mode = MP_IDLE;
        mp_state.elapsed = 0U;
        mp_output.realized_a_m2 = zero;
    } else if (oppose) {
        mp_state.mode = MP_REVERSAL_WAIT;
        mp_state.elapsed = 0U;
        mp_state.captured_a_m2 = zero;
        mp_output.realized_a_m2 = zero;
    } else {
        mp_state.captured_a_m2 = (adcs_vec3_t){capv[0], capv[1], capv[2]};
        mp_state.last_capture_a_m2 = mp_state.captured_a_m2;
        mp_state.mode = MP_PULSE;
        mp_state.elapsed = 1U;
        mp_state.thermal_cycles += 1U;
        if (mp_state.thermal_cycles >= mp_config.max_thermal_cycles) {
            /* 本次call达到上限 → emit零并进INHIBIT */
            mp_state.mode = MP_INHIBIT;
            mp_state.elapsed = 0U;
            mp_output.realized_a_m2 = zero;
        } else {
            mp_output.realized_a_m2 = mp_state.captured_a_m2;
        }
    }
} else if (mp_state.mode == MP_PULSE) {
    if (quiet) {
        mp_state.mode = MP_COOLDOWN;
        mp_state.elapsed = 0U;
        mp_output.realized_a_m2 = zero;
    } else {
        mp_state.thermal_cycles += 1U;
        mp_state.elapsed += 1U;
        if (mp_state.thermal_cycles >= mp_config.max_thermal_cycles) {
            mp_state.mode = MP_INHIBIT;
            mp_state.elapsed = 0U;
            mp_output.realized_a_m2 = zero;
        } else if (mp_state.elapsed >= mp_config.pulse_cycles) {
            mp_state.mode = MP_COOLDOWN;
            mp_state.elapsed = 0U;
            mp_output.realized_a_m2 = zero;
        } else {
            mp_output.realized_a_m2 = mp_state.captured_a_m2;
        }
    }
} else if (mp_state.mode == MP_COOLDOWN) {
    mp_output.realized_a_m2 = zero;
    mp_state.elapsed += 1U;
    if (mp_state.elapsed >= mp_config.cooldown_cycles) {
        mp_state.mode = MP_IDLE;
        mp_state.elapsed = 0U;
    }
} else if (mp_state.mode == MP_REVERSAL_WAIT) {
    mp_output.realized_a_m2 = zero;
    mp_state.elapsed += 1U;
    if (mp_state.elapsed >= mp_config.reversal_blank_cycles) {
        mp_state.mode = MP_IDLE;
        mp_state.elapsed = 0U;
        mp_state.last_capture_a_m2 = zero;
    }
} else if (mp_state.mode == MP_INHIBIT) {
    mp_output.realized_a_m2 = zero;
    if (quiet) {
        mp_state.recovery_count += 1U;
    } else {
        mp_state.recovery_count = 0U;
    }
    if (mp_state.recovery_count >= mp_config.recovery_cycles) {
        mp_state.mode = MP_IDLE;
        mp_state.elapsed = 0U;
        mp_state.thermal_cycles = 0U;
        mp_state.recovery_count = 0U;
    }
}

mp_output.torque_nm = adcs_vec3_cross(&mp_output.realized_a_m2, fld);

mp_output.mode = mp_state.mode;
mp_output.elapsed = mp_state.elapsed;
mp_output.thermal_cycles = mp_state.thermal_cycles;
mp_output.recovery_count = mp_state.recovery_count;

